var pts = [], line = document.getElementById('l');
Skypane.on('state', function (s) {
  var m = s.slots.meter, w = m ? parseFloat(m.attrs.power) : NaN;
  if (!isFinite(w)) return;
  var now = Date.now();
  if (!pts.length || now - pts[pts.length - 1][0] > 20000) pts.push([now, w]); else pts[pts.length - 1][1] = w;
  pts = pts.filter(function (p) { return now - p[0] < 3600000; });
  var max = Math.max.apply(null, pts.map(function (p) { return p[1]; }).concat([1]));
  line.setAttribute('points', pts.map(function (p) { return (300 - (now - p[0]) / 12000).toFixed(1) + ',' + (78 - (p[1] / max) * 74).toFixed(1); }).join(' '));
});
